import{_ as e,c as a,o,ag as l}from"./chunks/framework.xT_8jeIh.js";const m=JSON.parse('{"title":"循环语句","description":"","frontmatter":{},"headers":[],"relativePath":"5.loop-statements/index.md","filePath":"5.loop-statements/index.md"}'),r={name:"5.loop-statements/index.md"};function n(i,t,s,p,d,h){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="循环语句" tabindex="-1">循环语句 <a class="header-anchor" href="#循环语句" aria-label="Permalink to &quot;循环语句&quot;">​</a></h1><p>有时候我们会想让某些事情「重复做好多次」，比如让角色执行一连串重复的动作，批量更改节点的属性或是一下子生成一大堆东西 这时候，<strong>循环语句</strong>就派上用场了</p><p>本章将带你认识两种常见的循环方式：</p><ul><li><p><strong>while</strong> —— 只要条件成立，就一直重复执行，直到条件不满足为止</p></li><li><p><strong>for</strong> —— 适合次数明确的循环，用来遍历、计数、处理重复任务都很方便</p></li></ul><p>除此之外，我们还会认识两个跳转语句：</p><ul><li><p><strong>break</strong> —— 让你立刻跳出循环</p></li><li><p><strong>continue</strong> —— 让你跳过当前这轮，直接进入下一次迭代</p></li></ul><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><p><a href="./5.1.while-loop.html">while 循环</a></p></li><li><p><a href="./5.2.for-loop.html">for 循环</a></p></li><li><p><a href="./5.3.jump-statements.html">跳转语句</a></p></li></ul>',8)])])}const c=e(r,[["render",n]]);export{m as __pageData,c as default};
